// ====== НАСТРОЙКИ: правим только здесь ======
const CFG = {
  bitrix: 'https://your-portal.bitrix24.ru/rest/1/xxxxxxxx/', // входящий вебхук, со слэшем на конце
  managerId: 1,          // ответственный менеджер
  testLeadId: 0,         // ID лида для ручного запуска
  onlyTestLeads: true,   // обрабатываем только лиды с [ТЕСТ] в названии
  stopWords: ['seo', 'продвижение сайта', 'вакансия', 'бартер', 'рассылк', 'разместим рекламу'],
  hotWords: ['срочно', 'сегодня', 'завтра', 'бюджет', 'договор', 'тендер', 'оплатим']
};

const b = $input.first().json?.body ?? $input.first().json ?? {};
const leadId = Number(b?.data?.FIELDS?.ID ?? b?.leadId ?? CFG.testLeadId ?? 0);

return [{ json: { cfg: CFG, leadId } }];

// Очистка полей + проверка, можно ли обрабатывать + промпт для LLM
const cfg = $('Настройки').first().json.cfg;
const L = ($input.first().json || {}).result || {};

const clean = s => String(s ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const first = a => Array.isArray(a) && a.length ? String(a[0].VALUE || '').trim() : '';

const lead = {
  id: Number(L.ID || 0),
  title: clean(L.TITLE),
  name: clean([L.NAME, L.LAST_NAME].filter(Boolean).join(' ')),
  company: clean(L.COMPANY_TITLE),
  phone: first(L.PHONE),
  email: first(L.EMAIL).toLowerCase(),
  text: clean(L.COMMENTS) || clean(L.SOURCE_DESCRIPTION)
};

// обязательные поля
const missing = [];
if (!lead.name) missing.push('имя');
if (!lead.phone && !lead.email) missing.push('телефон или e-mail');
if (!lead.text || lead.text.length < 15) missing.push('описание запроса');

// два предохранителя: учебный лид и защита от повторной обработки
const isTest = !cfg.onlyTestLeads || lead.title.includes('[ТЕСТ]');
const already = clean(L.COMMENTS).includes('[AI]');
const canProcess = isTest && already === false && lead.id > 0;

const prompt = [
  'Заявка из CRM. Классифицируй её и предложи черновик ответа.',
  'Имя: ' + (lead.name || '—'),
  'Компания: ' + (lead.company || '—'),
  'Контакты: ' + (lead.phone || lead.email || 'нет'),
  'Текст: ' + (lead.text || '—'),
  missing.length ? 'Не хватает данных: ' + missing.join(', ') : ''
].filter(Boolean).join('\n');

const system = 'Ты ассистент отдела продаж. Ты только классифицируешь заявку и пишешь черновик ответа — ' +
  'ничего не отправляешь и не отказываешь клиенту. Ответь одним JSON без markdown: ' +
  '{"category":"target|potential|irrelevant|spam","summary":"1-2 предложения для менеджера",' +
  '"reply_draft":"черновик ответа клиенту, 3-5 предложений"}. Не выдумывай факты о клиенте.';

return [{ json: {
  leadId: lead.id, lead, missing, canProcess,
  skipReason: !isTest ? 'не учебный лид' : already ? 'уже обработан' : '',
  systemPrompt: system,
  userPrompt: prompt
}}];

// LLM предлагает — правила решают. Здесь считаются маршрут, приоритет и дедлайн.
const cfg = $('Настройки').first().json.cfg;
const d = $('Проверка лида').first().json;
const lead = d.lead;

// 1. читаем ответ LLM, при мусоре работаем без него
let ai = null;
const raw = $json.text ?? $json.output ?? $json?.choices?.[0]?.message?.content ?? '';
try { ai = JSON.parse(String(raw).replace(/```json|```/g, '').trim()); } catch (e) {}
const aiOk = !!ai && ['target','potential','irrelevant','spam'].includes(String(ai.category).toLowerCase());
const category = aiOk ? String(ai.category).toLowerCase() : 'unknown';

// 2. детерминированный скоринг
const hay = (lead.text + ' ' + lead.title).toLowerCase();
const isStop = cfg.stopWords.some(w => hay.includes(w));
const isHot  = cfg.hotWords.some(w => hay.includes(w));

let score = 0;
if (category === 'target') score += 40;
if (category === 'potential') score += 20;
if (category === 'irrelevant' || category === 'spam') score -= 50;
if (category === 'unknown') score += 20;   // сбой LLM не повод терять лид
if (isHot) score += 20;
if (lead.phone) score += 10;
if (isStop) score -= 60;

// 3. маршрут и приоритет
const route = d.missing.length ? 'НЕПОЛНЫЙ' : (isStop || score < 0) ? 'НЕРЕЛЕВАНТНЫЙ' : 'ЦЕЛЕВОЙ';
const priority = route !== 'ЦЕЛЕВОЙ' ? 'P3' : (score >= 60 ? 'P1' : score >= 30 ? 'P2' : 'P3');
const slaMin = { P1: 15, P2: 120, P3: 1440 }[priority];
const deadline = new Date(Date.now() + slaMin * 60000).toISOString();

// 4. черновик: шаблон для неполных и нерелевантных, LLM — для целевых
const hi = 'Здравствуйте' + (lead.name ? ', ' + lead.name.split(' ')[0] : '') + '!';
const draft =
  route === 'НЕПОЛНЫЙ'
    ? hi + '\nСпасибо за заявку. Чтобы ответить точно, не хватает данных: ' + d.missing.join(', ') +
      '.\nПодскажите, пожалуйста, эти детали — вернёмся с предложением в течение рабочего дня.'
  : route === 'НЕРЕЛЕВАНТНЫЙ'
    ? hi + '\nСпасибо за обращение. Похоже, запрос выходит за рамки нашей работы. Менеджер проверит заявку и ответит, если сможем помочь.'
  : (aiOk && ai.reply_draft) ? ai.reply_draft
    : hi + '\nСпасибо за заявку — менеджер свяжется с вами в ближайшее время.';

const summary = aiOk ? String(ai.summary || '') : 'LLM недоступна, квалификация по правилам.';

const task = [
  'Маршрут: ' + route + ' | Приоритет: ' + priority + ' | Скоринг: ' + score,
  'Резюме: ' + summary,
  d.missing.length ? 'Не хватает полей: ' + d.missing.join(', ') : 'Все обязательные поля заполнены',
  'Контакты: ' + (lead.phone || '—') + ' / ' + (lead.email || '—'),
  !aiOk ? 'ВНИМАНИЕ: ответ LLM не распознан, проверьте вручную' : '',
  '',
  'ЧЕРНОВИК ОТВЕТА (клиенту НЕ отправлен, отправляет менеджер после проверки):',
  draft
].filter(Boolean).join('\n');

return [{ json: {
  leadId: d.leadId, lead, route, priority, score, summary, draft, task, deadline, slaMin,
  aiOk, missing: d.missing, managerId: cfg.managerId
}}];

